  <style>
    :root {
      color-scheme: dark;
      --bg: #0b0f17;
      --surface: #111827;
      --surface-2: #172033;
      --surface-3: #1f2a44;
      --text: #f3f4f6;
      --muted: #a8b3c7;
      --accent: #7c9cff;
      --accent-strong: #9bb0ff;
      --danger: #ff6b7a;
      --border: #2b3955;
      --shadow: 0 30px 80px rgba(0, 0, 0, 0.5);
      --radius: 20px;
    }

    * {
      box-sizing: border-box;
    }

    html {
      color-scheme: dark;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, #16213b 0%, transparent 45%),
        linear-gradient(180deg, #090d15 0%, #0b1020 100%);
      color: var(--text);
    }

    a.skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      padding: 0.75rem 1rem;
      background: var(--accent);
      color: #08111f;
      border-radius: 999px;
      transform: translateY(-180%);
      transition: transform 0.2s ease;
      z-index: 1000;
      text-decoration: none;
      font-weight: 700;
    }

    a.skip-link:focus {
      transform: translateY(0);
      outline: 3px solid #fff;
      outline-offset: 2px;
    }

    main {
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 2rem 1rem;
    }

    .card {
      width: min(100%, 760px);
      background: linear-gradient(180deg, rgba(23, 32, 51, 0.95), rgba(13, 18, 31, 0.96));
      border: 1px solid var(--border);
      border-radius: calc(var(--radius) + 4px);
      box-shadow: var(--shadow);
      overflow: hidden;
    }

    .preview {
      display: grid;
      gap: 0;
    }

    .image-shell {
      background: linear-gradient(135deg, #10192b, #1a2840);
      padding: 1rem;
    }

    img.preview-image {
      display: block;
      width: 100%;
      max-width: 100%;
      height: auto;
      aspect-ratio: 16 / 10;
      object-fit: cover;
      border-radius: calc(var(--radius) - 8px);
      border: 1px solid rgba(255, 255, 255, 0.08);
      background: #0e1422;
    }

    .details {
      padding: 1.25rem 1.25rem 1.4rem;
      display: grid;
      gap: 0.85rem;
    }

    h1 {
      margin: 0;
      font-size: clamp(1.4rem, 2vw, 2rem);
      line-height: 1.15;
      letter-spacing: -0.02em;
    }

    p {
      margin: 0;
      color: var(--muted);
      line-height: 1.6;
      overflow-wrap: anywhere;
    }

    .actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.75rem;
      margin-top: 0.35rem;
    }

    button {
      appearance: none;
      border: 0;
      border-radius: 999px;
      padding: 0.9rem 1.15rem;
      font: inherit;
      font-weight: 700;
      color: var(--text);
      background: var(--surface-2);
      cursor: pointer;
      transition: transform 0.15s ease, background-color 0.15s ease, border-color 0.15s ease;
    }

    button:hover {
      background: var(--surface-3);
    }

    button:active {
      transform: translateY(1px);
    }

    button:focus-visible,
    a:focus-visible {
      outline: 3px solid var(--accent);
      outline-offset: 3px;
    }

    .trigger {
      background: linear-gradient(180deg, #26365d, #1f2f51);
      border: 1px solid #3c547f;
      color: var(--text);
    }

    .trigger:hover {
      background: linear-gradient(180deg, #31436e, #243559);
    }

    .secondary {
      background: transparent;
      border: 1px solid var(--border);
      color: var(--muted);
    }

    .secondary:hover {
      color: var(--text);
    }

    .destructive {
      background: linear-gradient(180deg, #ff7885, #e94f62);
      color: #18080b;
      box-shadow: 0 12px 28px rgba(233, 79, 98, 0.25);
    }

    .destructive:hover {
      background: linear-gradient(180deg, #ff8893, #f05f72);
    }

    .status {
      min-height: 1.5rem;
      color: var(--accent-strong);
      font-weight: 600;
    }

    dialog {
      width: min(92vw, 460px);
      border: 1px solid var(--border);
      border-radius: 24px;
      padding: 0;
      background: linear-gradient(180deg, #121a2c, #0d1321);
      color: var(--text);
      box-shadow: var(--shadow);
    }

    dialog::backdrop {
      background: rgba(4, 8, 16, 0.78);
      backdrop-filter: blur(6px);
    }

    .dialog-inner {
      padding: 1.25rem;
      display: grid;
      gap: 1rem;
    }

    .dialog-header {
      display: flex;
      gap: 0.85rem;
      align-items: flex-start;
    }

    .dialog-icon {
      flex: none;
      width: 2.8rem;
      height: 2.8rem;
      border-radius: 50%;
      display: grid;
      place-items: center;
      background: rgba(255, 107, 122, 0.15);
      color: var(--danger);
      border: 1px solid rgba(255, 107, 122, 0.3);
    }

    .dialog-icon svg {
      width: 1.4rem;
      height: 1.4rem;
      fill: currentColor;
    }

    .dialog-copy h2 {
      margin: 0 0 0.35rem;
      font-size: 1.15rem;
    }

    .dialog-copy p {
      font-size: 0.98rem;
    }

    .dialog-actions {
      display: flex;
      gap: 0.75rem;
      justify-content: flex-end;
      flex-wrap: wrap;
    }

    @media (max-width: 520px) {
      .details {
        padding: 1rem;
      }

      .dialog-actions {
        justify-content: stretch;
      }

      .dialog-actions button {
        flex: 1 1 100%;
      }
    }

    @media (forced-colors: active) {
      :root {
        --bg: Canvas;
        --surface: Canvas;
        --surface-2: ButtonFace;
        --surface-3: ButtonFace;
        --text: CanvasText;
        --muted: CanvasText;
        --accent: Highlight;
        --accent-strong: Highlight;
        --danger: Highlight;
        --border: ButtonBorder;
      }

      body,
      .card,
      dialog {
        background: Canvas;
        color: CanvasText;
        border-color: ButtonBorder;
      }

      .trigger,
      .secondary,
      .destructive,
      button {
        forced-color-adjust: auto;
        border: 1px solid ButtonBorder;
        color: ButtonText;
        background: ButtonFace;
      }

      dialog::backdrop {
        background: Canvas;
      }

      .dialog-icon {
        border-color: ButtonBorder;
      }
    }
  </style>
</head>
