     }

     .dialog-inner {
       padding: 1.25rem;
       display: grid;
       gap: 1rem;
     }

     .dialog-header {
       display: flex;
       gap: 0.85rem;
       align-items: flex-start;
     }

     .dialog-icon {
       flex: none;
       width: 2.8rem;
       height: 2.8rem;
       border-radius: 50%;
       display: grid;
       place-items: center;
       background: rgba(255, 107, 122, 0.15);
       color: var(--danger);
       border: 1px solid rgba(255, 107, 122, 0.3);
     }

     .dialog-icon svg {
       width: 1.4rem;
       height: 1.4rem;
       fill: currentColor;
     }

     .dialog-copy h2 {
       margin: 0 0 0.35rem;
       font-size: 1.15rem;
     }

     .dialog-copy p {
       font-size: 0.98rem;
     }

     .dialog-actions {
       display: flex;
       gap: 0.75rem;
       justify-content: flex-end;
       flex-wrap: wrap;
     }

     @media (max-width: 520px) {
       .details {
         padding: 1rem;
       }

       .dialog-actions {
         justify-content: stretch;
